-- swingset-phase: tables

-- Schema 37, ported from the frozen SQLite catalog. Do not execute against production SQLite.

-- All application integers retain SQLite signed 64-bit values.

CREATE SCHEMA IF NOT EXISTS "fetch";

CREATE SCHEMA IF NOT EXISTS "plan";

CREATE SCHEMA IF NOT EXISTS "evidence";

CREATE SCHEMA IF NOT EXISTS "derive";

CREATE SCHEMA IF NOT EXISTS "project";

CREATE SCHEMA IF NOT EXISTS "release";

CREATE SCHEMA IF NOT EXISTS "ops";

SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp;

REVOKE CREATE ON SCHEMA public FROM PUBLIC;

CREATE FUNCTION ops.compact_json(input text) RETURNS text
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE AS $fn$
DECLARE result text := ''; quoted boolean := false; escaped boolean := false; ch text; position integer;
BEGIN
 FOR position IN 1..length(input) LOOP
  ch := substr(input,position,1);
  IF quoted THEN
   result := result || ch;
   IF escaped THEN escaped := false;
   ELSIF ch=chr(92) THEN escaped := true;
   ELSIF ch='"' THEN quoted := false; END IF;
  ELSIF ch='"' THEN quoted := true; result := result || ch;
  ELSIF ch NOT IN (' ',chr(9),chr(10),chr(13)) THEN result := result || ch;
  END IF;
 END LOOP;
 RETURN result;
END $fn$;

CREATE FUNCTION ops.valid_json(input text) RETURNS boolean
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE AS $fn$
BEGIN PERFORM input::json; RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $fn$;

CREATE FUNCTION ops.compact_json(input json) RETURNS text LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS 'SELECT ops.compact_json(input::text)';
CREATE FUNCTION ops.compact_json(input jsonb) RETURNS text LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS 'SELECT ops.compact_json(input::text)';
CREATE FUNCTION ops.try_timestamp(input text) RETURNS timestamptz
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE SET timezone='UTC' SET datestyle='ISO,YMD' AS $fn$
BEGIN
 IF input !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}([T ][0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]+)?)?(Z|[+-][0-9]{2}(:?[0-9]{2})?)?)?$' THEN RETURN NULL; END IF;
 RETURN input::timestamptz;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation THEN RETURN NULL;
END $fn$;

