CREATE FUNCTION ops.schema_identity() RETURNS TABLE(key text,value text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,ops AS $fn$
SELECT meta.key,meta.value FROM ops.meta WHERE meta.key='schema_version'
UNION ALL SELECT 'postgres_migration_checksum',obj_description('ops'::regnamespace,'pg_namespace')::json->>'migration_checksum'
$fn$;

CREATE FUNCTION ops.wal_size() RETURNS bigint
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog AS $fn$
SELECT coalesce(sum(size),0)::bigint FROM pg_catalog.pg_ls_waldir()
$fn$;

CREATE FUNCTION ops.text_bytes(input text,start_byte integer,byte_count integer) RETURNS bytea
LANGUAGE internal IMMUTABLE STRICT PARALLEL SAFE AS 'bytea_substr';
