CREATE INDEX source_units_accepted_idx ON "evidence"."source_units"(accepted_generation_id);

CREATE INDEX source_units_legacy_idx ON "evidence"."source_units"(legacy_snapshot_id);

CREATE INDEX source_units_watch_idx ON "evidence"."source_units"(watch_id);

CREATE INDEX watches_due_idx ON "fetch"."watches"(state, priority DESC, next_check_at);

CREATE INDEX watches_event_blockers ON "fetch"."watches"(source,source_ref,watch_id);

CREATE INDEX watches_kind_watch_idx ON "fetch"."watches"(kind,watch_id);

CREATE INDEX watches_parent_watch_id_fk_idx ON "fetch"."watches"(parent_watch_id);

CREATE INDEX work_attempts_run ON "derive"."work_attempts"(run_id);

CREATE INDEX work_attempts_running ON "derive"."work_attempts"(outcome,attempt_id);

CREATE INDEX work_attempts_unit ON "derive"."work_attempts"(stage,unit_kind,unit_id,attempt_id DESC);

CREATE INDEX work_queue_due ON "derive"."work_queue"(state, next_attempt_at);

CREATE VIEW "derive"."derivation_rows"(generation_id,ordinal,table_name,record_key,payload_json) AS
SELECT r.generation_id,r.ordinal,r.table_name,r.record_key,p.payload_json
FROM derivation_row_refs r JOIN derivation_payloads p ON p.payload_sha256=r.payload_sha256;

