CREATE FUNCTION "derive"."tr_derivation_generation_no_update"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM storage_eviction_authority)
    OR NEW.generation_id IS DISTINCT FROM OLD.generation_id OR NEW.stage IS DISTINCT FROM OLD.stage
    OR NEW.unit_kind IS DISTINCT FROM OLD.unit_kind OR NEW.unit_id IS DISTINCT FROM OLD.unit_id
    OR NEW.input_fingerprint IS DISTINCT FROM OLD.input_fingerprint
    OR NEW.dependency_set_id IS DISTINCT FROM OLD.dependency_set_id
    OR NEW.previous_generation_id IS DISTINCT FROM OLD.previous_generation_id
    OR NEW.output_digest IS DISTINCT FROM OLD.output_digest OR NEW.row_count IS DISTINCT FROM OLD.row_count
    OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.run_id IS DISTINCT FROM OLD.run_id
    OR NOT (
        (OLD.stage='build' AND OLD.recipe_json<>'{"packed":true}'
            AND NEW.recipe_json='{"packed":true}'
            AND EXISTS (SELECT 1 FROM label_body_packs p WHERE p.generation_id=OLD.generation_id))
        OR (OLD.recipe_json='{"packed":true}' AND NEW.recipe_json<>'{"packed":true}')
    ) THEN
 RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='derivation generations are immutable';
 END IF;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "derivation_generation_no_update" BEFORE UPDATE ON "derive"."derivation_generations" FOR EACH ROW EXECUTE FUNCTION "derive"."tr_derivation_generation_no_update"();

