LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO derivation_input_versions(namespace,input_key,version)
 SELECT 'raw',ops.compact_json(json_build_array(scope_kind,scope_id)::text),1 FROM observations
 WHERE observation_id=NEW.observation_id OR (watch_id=NEW.watch_id AND snapshot_id=NEW.snapshot_id AND kind=NEW.kind AND seq=NEW.seq)
 ON CONFLICT(namespace,input_key) DO UPDATE SET version=derivation_input_versions.version+1;
 RETURN NEW;
END $fn$;

