 INSERT INTO derivation_scopes(stage,unit_kind,unit_id,registered_at) SELECT 'project',OLD.scope_kind,OLD.scope_id,(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS')||'+00:00') WHERE OLD.scope_kind IN ('calendar','source_index','dancer','event','source_event','inventory','map','history') AND NOT EXISTS (SELECT 1 FROM derivation_scopes WHERE stage='project' AND unit_kind=OLD.scope_kind AND unit_id=OLD.scope_id) ON CONFLICT DO NOTHING;
 RETURN OLD;
END $fn$;

