CREATE FUNCTION "project"."tr_derivation_source_event_map_delete"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO derivation_input_versions ("namespace","input_key","version") VALUES ('mapping',OLD.event_id,1) ON CONFLICT(namespace,input_key) DO UPDATE SET version=derivation_input_versions.version+1;
 INSERT INTO derivation_input_versions ("namespace","input_key","version") VALUES ('source_mapping',OLD.source_ref,1) ON CONFLICT(namespace,input_key) DO UPDATE SET version=derivation_input_versions.version+1;
 INSERT INTO derivation_scopes(stage,unit_kind,unit_id,registered_at) SELECT 'project','event',OLD.event_id,(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS')||'+00:00') WHERE 'event' IN ('calendar','source_index','dancer','event','source_event','inventory','map','history') AND NOT EXISTS (SELECT 1 FROM derivation_scopes WHERE stage='project' AND unit_kind='event' AND unit_id=OLD.event_id) ON CONFLICT DO NOTHING;
 INSERT INTO derivation_scopes(stage,unit_kind,unit_id,registered_at) SELECT 'project','source_event',OLD.source_ref,(to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS')||'+00:00') WHERE 'source_event' IN ('calendar','source_index','dancer','event','source_event','inventory','map','history') AND NOT EXISTS (SELECT 1 FROM derivation_scopes WHERE stage='project' AND unit_kind='source_event' AND unit_id=OLD.source_ref) ON CONFLICT DO NOTHING;
 RETURN OLD;
