CREATE FUNCTION "derive"."tr_derivation_version_monotonic"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 IF NEW.namespace IS DISTINCT FROM OLD.namespace OR NEW.input_key IS DISTINCT FROM OLD.input_key OR NEW.version <= OLD.version THEN
 RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='derivation input versions must advance';
 END IF;
 RETURN NEW;
END $fn$;

