CREATE FUNCTION "evidence"."tr_gap_generation_delete"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO event_gap_revisions
    ("source","revision") SELECT w.source,1 FROM source_units u JOIN watches w USING(watch_id)
    WHERE u.unit_key=OLD.unit_key
    ON CONFLICT(source) DO UPDATE SET revision=event_gap_revisions.revision+1;
 RETURN OLD;
END $fn$;

CREATE TRIGGER "gap_generation_delete" AFTER DELETE ON "evidence"."source_generations" FOR EACH ROW EXECUTE FUNCTION "evidence"."tr_gap_generation_delete"();

CREATE FUNCTION "evidence"."tr_gap_generation_insert"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO event_gap_revisions
    ("source","revision") SELECT w.source,1 FROM source_units u JOIN watches w USING(watch_id)
    WHERE u.unit_key=NEW.unit_key
    ON CONFLICT(source) DO UPDATE SET revision=event_gap_revisions.revision+1;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "gap_generation_insert" AFTER INSERT ON "evidence"."source_generations" FOR EACH ROW EXECUTE FUNCTION "evidence"."tr_gap_generation_insert"();

CREATE FUNCTION "evidence"."tr_gap_generation_update"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO event_gap_revisions
    ("source","revision") SELECT DISTINCT w.source,1 FROM source_units u JOIN watches w USING(watch_id)
    WHERE u.unit_key IN (OLD.unit_key,NEW.unit_key)
    ON CONFLICT(source) DO UPDATE SET revision=event_gap_revisions.revision+1;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "gap_generation_update" AFTER UPDATE ON "evidence"."source_generations" FOR EACH ROW EXECUTE FUNCTION "evidence"."tr_gap_generation_update"();

