CREATE FUNCTION "fetch"."tr_gap_snapshot_support_rewrite"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 IF OLD.classification IS DISTINCT FROM NEW.classification OR OLD.via IS DISTINCT FROM NEW.via
 OR OLD.fetched_at IS DISTINCT FROM NEW.fetched_at OR OLD.http_status IS DISTINCT FROM NEW.http_status
 OR OLD.captured_at IS DISTINCT FROM NEW.captured_at THEN
 UPDATE event_pressure_state SET epoch=epoch+1;
 END IF;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "gap_snapshot_support_rewrite" AFTER UPDATE OF CLASSIFICATION,VIA,FETCHED_AT,HTTP_STATUS,CAPTURED_AT ON "fetch"."snapshots" FOR EACH ROW EXECUTE FUNCTION "fetch"."tr_gap_snapshot_support_rewrite"();

CREATE FUNCTION "evidence"."tr_gap_unit_watch_change"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 IF OLD.watch_id IS DISTINCT FROM NEW.watch_id THEN
 INSERT INTO event_gap_revisions
    ("source","revision") SELECT DISTINCT source,1 FROM watches WHERE watch_id IN (OLD.watch_id,NEW.watch_id)
    ON CONFLICT(source) DO UPDATE SET revision=event_gap_revisions.revision+1;
 END IF;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "gap_unit_watch_change" AFTER UPDATE OF WATCH_ID ON "evidence"."source_units" FOR EACH ROW EXECUTE FUNCTION "evidence"."tr_gap_unit_watch_change"();

CREATE FUNCTION "fetch"."tr_gap_watch_delete"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO event_gap_revisions ("source","revision") VALUES(OLD.source,1) ON CONFLICT(source) DO UPDATE SET revision=event_gap_revisions.revision+1;
 RETURN OLD;
END $fn$;

CREATE TRIGGER "gap_watch_delete" BEFORE DELETE ON "fetch"."watches" FOR EACH ROW EXECUTE FUNCTION "fetch"."tr_gap_watch_delete"();

CREATE FUNCTION "fetch"."tr_gap_watch_source"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 IF OLD.source IS DISTINCT FROM NEW.source THEN
 INSERT INTO event_gap_revisions ("source","revision") VALUES(OLD.source,1) ON CONFLICT(source) DO UPDATE SET revision=event_gap_revisions.revision+1;
 INSERT INTO event_gap_revisions ("source","revision") VALUES(NEW.source,1) ON CONFLICT(source) DO UPDATE SET revision=event_gap_revisions.revision+1;
 UPDATE event_pressure_state SET epoch=epoch+1;
 END IF;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "gap_watch_source" AFTER UPDATE OF SOURCE ON "fetch"."watches" FOR EACH ROW EXECUTE FUNCTION "fetch"."tr_gap_watch_source"();

