CREATE FUNCTION "project"."tr_identity_links_retain_deleted"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO identity_link_history(subject_kind,subject_id,state,assertion_json,resolution_json,recorded_at)
    VALUES (
        OLD.subject_kind,OLD.subject_id,'superseded',
        ops.compact_json(json_build_object('link_id',OLD.link_id,'wsdc_id',OLD.wsdc_id,'method',OLD.method,'status',OLD.status,'confidence',OLD.confidence,'constraints_applied',OLD.constraints_applied,'asserted_at',OLD.asserted_at,'run_id',OLD.run_id,'linker_version',OLD.linker_version)::text),
        COALESCE((SELECT ops.compact_json(json_build_object('ref_ids',ref_ids_json,'decision_ids',decision_ids_json,'policy_version',policy_version,'journal_digest',journal_digest,'journal_generation',journal_generation,'state',state,'reason',reason)::text) FROM identity_link_resolutions WHERE subject_kind=OLD.subject_kind AND subject_id=OLD.subject_id),'{}'),
        (to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS')||'Z')
    );
 UPDATE identity_link_resolutions SET state='superseded' WHERE subject_kind=OLD.subject_kind AND subject_id=OLD.subject_id;
 RETURN OLD;
END $fn$;

CREATE TRIGGER "identity_links_retain_deleted" AFTER DELETE ON "project"."identity_links" FOR EACH ROW EXECUTE FUNCTION "project"."tr_identity_links_retain_deleted"();

