CREATE FUNCTION "evidence"."tr_pressure_admission_insert"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO event_pressure_dirty
        ("watch_id") SELECT u.watch_id FROM source_units u JOIN source_generations g USING(unit_key) WHERE g.generation_id=NEW.generation_id ON CONFLICT(watch_id) DO NOTHING;
 UPDATE event_pressure_subjects SET revision=revision+1 WHERE (source,source_ref) IN
        (SELECT p.source,p.source_ref FROM event_pressure_watches p JOIN source_units u USING(watch_id)
         JOIN source_generations g USING(unit_key) WHERE g.generation_id=NEW.generation_id);
 -- Shared platform indexes support events without being event requests.
    -- Watch identity also covers distinct capture units of the same parent.
    UPDATE event_pressure_subjects SET revision=revision+1 WHERE (source,source_ref) IN
        (SELECT p.source,p.source_ref FROM event_pressure_parents p
         JOIN source_units u USING(watch_id) JOIN source_generations changed USING(unit_key)
         WHERE changed.generation_id=NEW.generation_id);
 RETURN NEW;
END $fn$;

CREATE TRIGGER "pressure_admission_insert" AFTER INSERT ON "evidence"."admission_decisions" FOR EACH ROW EXECUTE FUNCTION "evidence"."tr_pressure_admission_insert"();

CREATE FUNCTION "plan"."tr_pressure_enumeration_change"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 DELETE FROM event_pressure_parents WHERE source=NEW.source AND source_ref=NEW.source_ref;
 INSERT INTO event_pressure_parents
        ("watch_id","source","source_ref") SELECT DISTINCT u.watch_id,NEW.source,NEW.source_ref FROM source_event_enumerations e
        CROSS JOIN LATERAL jsonb_each((e.parent_support_json)::jsonb) parent JOIN source_generations g ON g.generation_id=parent.key
        JOIN source_units u USING(unit_key) WHERE e.enumeration_id=NEW.enumeration_id
        ON CONFLICT(watch_id,source,source_ref) DO NOTHING;
 UPDATE event_pressure_subjects SET revision=revision+1 WHERE source=NEW.source AND source_ref=NEW.source_ref;
 INSERT INTO event_pressure_dirty
        ("watch_id") SELECT watch_id FROM source_event_member_watches WHERE enumeration_id=NEW.enumeration_id ON CONFLICT(watch_id) DO NOTHING;
 INSERT INTO event_pressure_dirty
        ("watch_id") SELECT watch_id FROM event_pressure_watches WHERE source=NEW.source AND source_ref=NEW.source_ref ON CONFLICT(watch_id) DO NOTHING;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "pressure_enumeration_change" AFTER UPDATE OF ENUMERATION_ID ON "plan"."source_event_inventory" FOR EACH ROW EXECUTE FUNCTION "plan"."tr_pressure_enumeration_change"();

