LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO event_pressure_dirty ("watch_id") VALUES (NEW.watch_id) ON CONFLICT(watch_id) DO NOTHING;
 INSERT INTO event_pressure_dirty ("watch_id") VALUES (OLD.watch_id) ON CONFLICT(watch_id) DO NOTHING;
 UPDATE event_pressure_subjects SET revision=revision+1 WHERE (source,source_ref) IN
        (SELECT source,source_ref FROM event_pressure_watches WHERE watch_id IN (OLD.watch_id,NEW.watch_id));
 RETURN NEW;
END $fn$;

