CREATE FUNCTION "ops"."tr_retention_apply_no_rewrite"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 IF old.files_completed_at IS NOT NULL
    OR old.receipt_json IS NOT NULL
    OR new.plan_digest <> old.plan_digest
    OR new.planned_files_json <> old.planned_files_json
    OR new.planned_payloads_json <> old.planned_payloads_json
    OR new.removed_payload_bytes <> old.removed_payload_bytes
    OR new.started_at <> old.started_at THEN
 RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='a retention apply note is written once and finished once';
 END IF;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "retention_apply_no_rewrite" BEFORE UPDATE ON "ops"."retention_applies" FOR EACH ROW EXECUTE FUNCTION "ops"."tr_retention_apply_no_rewrite"();

