CREATE FUNCTION "evidence"."tr_source_generation_immutable"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM storage_eviction_authority)
    OR NEW.unit_key IS DISTINCT FROM OLD.unit_key OR NEW.page_kind IS DISTINCT FROM OLD.page_kind
    OR NEW.contract_version IS DISTINCT FROM OLD.contract_version
    OR NEW.input_fingerprint IS DISTINCT FROM OLD.input_fingerprint
    OR NEW.recipe_json IS DISTINCT FROM OLD.recipe_json
    OR NEW.previous_generation_id IS DISTINCT FROM OLD.previous_generation_id
    OR NEW.work_token IS DISTINCT FROM OLD.work_token OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.run_id IS DISTINCT FROM OLD.run_id OR NEW.removal_authority IS DISTINCT FROM OLD.removal_authority
    OR NOT (
        (OLD.manifest_json<>'{"packed":true}' AND OLD.result_json<>'{"packed":true}'
            AND OLD.report_json<>'{"packed":true}'
            AND NEW.manifest_json='{"packed":true}' AND NEW.result_json='{"packed":true}'
            AND NEW.report_json='{"packed":true}'
            AND EXISTS (SELECT 1 FROM source_generation_packs p WHERE p.generation_id=OLD.generation_id))
        OR (OLD.manifest_json='{"packed":true}' AND OLD.result_json='{"packed":true}'
            AND OLD.report_json='{"packed":true}'
            AND NEW.manifest_json<>'{"packed":true}' AND NEW.result_json<>'{"packed":true}'
            AND NEW.report_json<>'{"packed":true}')
    ) THEN
 RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='source generation evidence is immutable';
 END IF;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "source_generation_immutable" BEFORE UPDATE OF UNIT_KEY,PAGE_KIND,CONTRACT_VERSION,INPUT_FINGERPRINT,MANIFEST_JSON,RECIPE_JSON,RESULT_JSON,REPORT_JSON,PREVIOUS_GENERATION_ID,WORK_TOKEN,CREATED_AT,RUN_ID,REMOVAL_AUTHORITY ON "evidence"."source_generations" FOR EACH ROW EXECUTE FUNCTION "evidence"."tr_source_generation_immutable"();

