LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM storage_eviction_authority)
    OR EXISTS (SELECT 1 FROM source_generations s WHERE s.generation_id=OLD.generation_id
        AND s.result_json='{"packed":true}') THEN
 RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='body pack removal requires authority and a restored row';
 END IF;
 RETURN OLD;
END $fn$;

