 IF OLD.finished_at IS NOT NULL
    OR NEW.plan_digest IS DISTINCT FROM OLD.plan_digest OR NEW.kind IS DISTINCT FROM OLD.kind
    OR NEW.started_at IS DISTINCT FROM OLD.started_at THEN
 RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='a storage apply note is written once and finished once';
 END IF;
