CREATE FUNCTION "derive"."tr_work_enqueued"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 INSERT INTO work_generations(stage,unit_kind,unit_id,generation)
    VALUES(NEW.stage,NEW.unit_kind,NEW.unit_id,1)
    ON CONFLICT(stage,unit_kind,unit_id) DO UPDATE SET generation=work_generations.generation+1;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "work_enqueued" AFTER INSERT ON "derive"."pending_work" FOR EACH ROW EXECUTE FUNCTION "derive"."tr_work_enqueued"();

CREATE FUNCTION "derive"."tr_work_invalidated"() RETURNS trigger
LANGUAGE plpgsql SET search_path=pg_catalog,"fetch",plan,evidence,derive,project,release,ops,pg_temp AS $fn$
BEGIN
 UPDATE work_generations SET generation=generation+1
    WHERE stage=NEW.stage AND unit_kind=NEW.unit_kind AND unit_id=NEW.unit_id;
 RETURN NEW;
END $fn$;

CREATE TRIGGER "work_invalidated" AFTER UPDATE ON "derive"."pending_work" FOR EACH ROW EXECUTE FUNCTION "derive"."tr_work_invalidated"();

